<?php $this->assign('title', 'Pagos | CatOps Admin'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><h1 class="h2 mb-1">Pagos</h1><p class="text-muted mb-0"><?= (int)$pagination['total'] ?> resultados.</p></div></div>
<section class="card admin-card mb-4"><div class="card-body"><form class="row g-2" method="get"><div class="col-12 col-md-4"><input class="form-control" name="q" value="<?= h($filters['q']) ?>" placeholder="Referencia, orden o correo"></div><div class="col-6 col-md-2"><select class="form-select" name="status"><option value="">Estado</option><?php foreach (['pending', 'authorized', 'paid', 'rejected', 'canceled', 'expired', 'reversed', 'failed'] as $status): ?><option value="<?= $status ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-2"><input class="form-control" name="provider" value="<?= h($filters['provider']) ?>" placeholder="Proveedor"></div><div class="col-6 col-md-2"><select class="form-select" name="plan"><option value="">Plan</option><?php foreach ($plans as $slug => $name): ?><option value="<?= h($slug) ?>" <?= $filters['plan'] === $slug ? 'selected' : '' ?>><?= h($name) ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-2"><button class="btn btn-primary w-100">Buscar</button></div></form></div></section>
<section class="card admin-card"><div class="table-wrap"><table class="table align-middle"><thead><tr><th>Referencia</th><th>Usuario</th><th>Plan</th><th>Monto</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody><?php foreach ($pagination['items'] as $payment): ?><tr><td><strong><?= h($payment->internal_reference) ?></strong><small class="d-block text-muted"><?= h($payment->provider) ?></small></td><td><?= h($payment->user->email ?? '') ?></td><td><?= h($payment->plan_slug) ?></td><td>$<?= number_format((int)$payment->amount, 0, ',', '.') ?></td><td><span class="badge text-bg-secondary badge-status"><?= h($payment->status) ?></span></td><td><?= h($payment->created) ?></td><td><a class="btn btn-sm btn-outline-primary" href="/admin/payments/<?= (int)$payment->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div><div class="card-body"><?= $this->element('admin_pagination', compact('pagination')) ?></div></section>
